package com.oanarinaldi.wakemeup;
import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import androidx.activity.ComponentActivity;import androidx.camera.core.*;import androidx.camera.lifecycle.ProcessCameraProvider;import androidx.camera.view.PreviewView;import androidx.core.content.ContextCompat;import org.tensorflow.lite.Interpreter;import org.tensorflow.lite.DataType;import java.nio.*;import com.google.zxing.*;import com.google.zxing.common.HybridBinarizer;import java.util.*;import java.util.concurrent.*;
/** Bundled MoveNet/LiteRT and ZXing process transient camera frames entirely on device. */
public class CameraActivity extends ComponentActivity {
 ExecutorService executor=Executors.newSingleThreadExecutor();Interpreter detector;MultiFormatReader scanner;volatile boolean done=false;boolean pose=false,armed=false,lowered=false;int count=0,target=5;long lastRep=0;TextView status;ProcessCameraProvider provider;
 public void onCreate(Bundle b){super.onCreate(b);String purpose=getIntent().getStringExtra("purpose");pose=purpose!=null&&purpose.startsWith("pose:");if(pose)try{target=Integer.parseInt(purpose.substring(5));}catch(Exception ignored){}getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);LinearLayout layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.setBackgroundColor(0xfffcf7ed);layout.setPadding(dp(24),dp(50),dp(24),dp(40));status=new TextView(this);status.setTextColor(0xff382640);status.setTextSize(20);status.setText(pose?"Push-ups · 0 / "+target+"\nKeep your whole body in a secure side view.":"Scan your destination code");layout.addView(status);PreviewView preview=new PreviewView(this);layout.addView(preview,new LinearLayout.LayoutParams(-1,0,1));TextView note=new TextView(this);note.setText("On-device only · no recording or upload\n"+(pose?"Counts are estimates. Move within your comfort.":"Point the camera at your barcode or QR code."));note.setPadding(0,dp(16),0,dp(16));layout.addView(note);Button exit=new Button(this);exit.setText("Back to guided mode");exit.setOnClickListener(v->finish());layout.addView(exit);setContentView(layout);
  var future=ProcessCameraProvider.getInstance(this);future.addListener(()->{try{provider=future.get();Preview p=new Preview.Builder().build();p.setSurfaceProvider(preview.getSurfaceProvider());ImageAnalysis analysis=new ImageAnalysis.Builder().setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST).setTargetResolution(new android.util.Size(640,480)).build();analysis.setAnalyzer(executor,image->{if(done){image.close();return;}Bitmap bitmap=null;try{bitmap=image.toBitmap();int rotation=image.getImageInfo().getRotationDegrees();if(rotation!=0){Matrix matrix=new Matrix();matrix.postRotate(rotation);Bitmap rotated=Bitmap.createBitmap(bitmap,0,0,bitmap.getWidth(),bitmap.getHeight(),matrix,true);if(rotated!=bitmap)bitmap.recycle();bitmap=rotated;}
    if(pose){if(detector==null){try(var in=getAssets().open("movenet_lightning.tflite")){java.io.ByteArrayOutputStream output=new java.io.ByteArrayOutputStream();byte[] chunk=new byte[8192];int n;while((n=in.read(chunk))>0)output.write(chunk,0,n);byte[] model=output.toByteArray();ByteBuffer bytes=ByteBuffer.allocateDirect(model.length).order(ByteOrder.nativeOrder());bytes.put(model);bytes.rewind();detector=new Interpreter(bytes,new Interpreter.Options().setNumThreads(2));}}int[] shape=detector.getInputTensor(0).shape();int h=shape[1],w=shape[2];Bitmap scaled=Bitmap.createScaledBitmap(bitmap,w,h,true);int[] rgb=new int[w*h];scaled.getPixels(rgb,0,w,0,0,w,h);DataType type=detector.getInputTensor(0).dataType();ByteBuffer input=ByteBuffer.allocateDirect(w*h*3*(type==DataType.UINT8?1:4)).order(ByteOrder.nativeOrder());for(int color:rgb)for(int value:new int[]{(color>>16)&255,(color>>8)&255,color&255}){if(type==DataType.INT32)input.putInt(value);else if(type==DataType.UINT8)input.put((byte)value);else input.putFloat(value);}input.rewind();float[][][][] output=new float[1][1][17][3];detector.run(input,output);consume(output[0][0],bitmap.getWidth()/(double)bitmap.getHeight());if(scaled!=bitmap)scaled.recycle();}
    else{if(scanner==null){scanner=new MultiFormatReader();Map<DecodeHintType,Object> hints=new EnumMap<>(DecodeHintType.class);hints.put(DecodeHintType.TRY_HARDER,true);scanner.setHints(hints);}int w=bitmap.getWidth(),h=bitmap.getHeight();int[] pixels=new int[w*h];bitmap.getPixels(pixels,0,w,0,0,w,h);try{Result result=scanner.decodeWithState(new BinaryBitmap(new HybridBinarizer(new RGBLuminanceSource(w,h,pixels))));finishResult(result.getText());}catch(NotFoundException ignored){}finally{scanner.reset();}}
   }catch(Exception e){runOnUiThread(()->status.setText("Keep your whole body or destination code in view. Guided mode always works."));}finally{if(bitmap!=null&&!bitmap.isRecycled())bitmap.recycle();image.close();}});CameraSelector select=pose&&provider.hasCamera(CameraSelector.DEFAULT_FRONT_CAMERA)?CameraSelector.DEFAULT_FRONT_CAMERA:CameraSelector.DEFAULT_BACK_CAMERA;provider.bindToLifecycle(this,select,p,analysis);}catch(Exception e){status.setText("Camera unavailable. Guided mode always works.");}},ContextCompat.getMainExecutor(this));
 }
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 void consume(float[][] points,double aspect){int offset=(points[5][2]+points[7][2]+points[9][2])>=(points[6][2]+points[8][2]+points[10][2])?0:1;float[] shoulder=points[5+offset],elbow=points[7+offset],wrist=points[9+offset];if(Math.min(shoulder[2],Math.min(elbow[2],wrist[2]))<.5){armed=false;lowered=false;return;}double ax=(shoulder[1]-elbow[1])*aspect,ay=shoulder[0]-elbow[0],bx=(wrist[1]-elbow[1])*aspect,by=wrist[0]-elbow[0];double angle=Math.toDegrees(Math.acos(Math.max(-1,Math.min(1,(ax*bx+ay*by)/(Math.hypot(ax,ay)*Math.hypot(bx,by))))));long now=SystemClock.elapsedRealtime();if(angle>150){if(armed&&lowered&&now-lastRep>=900){count++;lastRep=now;lowered=false;runOnUiThread(()->status.setText("Push-ups · "+count+" / "+target+"\nCamera estimate · stop anytime"));if(count>=target)finishResult("pose:"+count);}armed=true;}else if(angle<100&&armed)lowered=true;}
 void finishResult(String value){if(done)return;done=true;runOnUiThread(()->{setResult(RESULT_OK,new Intent().putExtra("result",value));finish();});}
 public void onDestroy(){done=true;if(provider!=null)provider.unbindAll();executor.execute(()->{if(detector!=null)detector.close();});executor.shutdown();super.onDestroy();}
}
